import { createHash } from "node:crypto";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, posix } from "node:path";
import * as core from "@actions/core";
import * as github from "@actions/github";

const ARTIFACT_TYPES = {
  skill: "SKILL.md",
  rule: "RULE.md",
  knowledge: "KNOWLEDGE.md",
};

/** Files managed locally by the registry — never synced from upstream. */
const LOCAL_ONLY = new Set(["metadata.json"]);

// --- Helpers ----------------------------------------------------------------

function parseGitHubUrl(url) {
  const match = url.match(/github\.com\/([^/]+)\/([^/.]+)/);
  if (!match) throw new Error(`Cannot parse GitHub URL: ${url}`);
  return { owner: match[1], repo: match[2] };
}

function gitBlobSha(content) {
  const buf = Buffer.isBuffer(content) ? content : Buffer.from(content);
  const header = `blob ${buf.length}\0`;
  return createHash("sha1").update(header).update(buf).digest("hex");
}

/** Walk a local directory recursively and return relative paths (posix-style). */
function walkDir(dir, base = dir) {
  const results = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...walkDir(full, base));
    } else {
      results.push(posix.normalize(relative(base, full)));
    }
  }
  return results;
}

/**
 * Resolve a subtree SHA by walking path components from a root tree.
 * Returns the tree SHA for the directory at `path`, or null if not found.
 */
async function resolveSubtreeSha(octokit, owner, repo, rootTreeSha, path) {
  const segments = path.split("/").filter(Boolean);
  let currentSha = rootTreeSha;

  for (const segment of segments) {
    const { data: tree } = await octokit.rest.git.getTree({
      owner,
      repo,
      tree_sha: currentSha,
    });
    const entry = tree.tree.find((e) => e.path === segment && e.type === "tree");
    if (!entry) return null;
    currentSha = entry.sha;
  }
  return currentSha;
}

function buildPrBody(upstream, date) {
  return [
    `Upstream source changed: ${upstream.url}`,
    `Path: ${upstream.path}`,
    `Ref: ${upstream.ref}`,
    `Last checked: ${date}`,
    "",
    "Auto-generated by renovate.yml. Review the diff carefully before merging \u2014",
    "this change came from an external source.",
    "",
    "If the local version has diverged intentionally, resolve conflicts in favour",
    "of the local version and close this PR.",
  ].join("\n");
}

// --- Main -------------------------------------------------------------------

const token = process.env.GITHUB_TOKEN;
if (!token) {
  core.setFailed("GITHUB_TOKEN is required");
  process.exit(1);
}

const octokit = github.getOctokit(token);
const [repoOwner, repoName] = process.env.GITHUB_REPOSITORY.split("/");
const today = new Date().toISOString().slice(0, 10);

// Load marketplace index
const marketplace = JSON.parse(readFileSync("marketplace.json", "utf8"));
const tracked = marketplace.packages.filter((p) => p.upstream);

if (tracked.length === 0) {
  core.info("No tracked packages found.");
  process.exit(0);
}

core.info(`Found ${tracked.length} tracked package(s).`);

for (const pkg of tracked) {
  try {
    await syncPackage(pkg);
  } catch (err) {
    core.warning(`[${pkg.name}] Sync failed: ${err.message}`);
  }
}

// --- Per-package sync -------------------------------------------------------

async function syncPackage(pkg) {
  const { name, upstream } = pkg;
  const { owner: upOwner, repo: upRepo } = parseGitHubUrl(upstream.url);
  const localDir = join("packages", name);
  const branchName = `sync/${name}`;

  core.info(`[${name}] Checking upstream ${upOwner}/${upRepo} @ ${upstream.ref}`);

  // 1. Resolve upstream ref to a commit SHA
  let commitSha;
  try {
    const { data: refData } = await octokit.rest.git.getRef({
      owner: upOwner,
      repo: upRepo,
      ref: `heads/${upstream.ref}`,
    });
    commitSha = refData.object.sha;
  } catch {
    // Try as a tag
    try {
      const { data: refData } = await octokit.rest.git.getRef({
        owner: upOwner,
        repo: upRepo,
        ref: `tags/${upstream.ref}`,
      });
      commitSha =
        refData.object.type === "tag"
          ? (await octokit.rest.git.getTag({ owner: upOwner, repo: upRepo, tag_sha: refData.object.sha })).data.object.sha
          : refData.object.sha;
    } catch {
      throw new Error(`Could not resolve ref '${upstream.ref}'`);
    }
  }

  // 2. Get the commit's root tree, then resolve the subtree for upstream.path
  const { data: commit } = await octokit.rest.git.getCommit({
    owner: upOwner,
    repo: upRepo,
    commit_sha: commitSha,
  });

  // Determine if upstream.path is a file or directory by trying subtree first
  let upstreamFiles; // Array of { path: relative, sha }

  const subtreeSha = await resolveSubtreeSha(
    octokit,
    upOwner,
    upRepo,
    commit.tree.sha,
    upstream.path,
  );

  if (subtreeSha) {
    // Directory mode — get full recursive tree
    const { data: subtree } = await octokit.rest.git.getTree({
      owner: upOwner,
      repo: upRepo,
      tree_sha: subtreeSha,
      recursive: "true",
    });
    upstreamFiles = subtree.tree
      .filter((e) => e.type === "blob" && !LOCAL_ONLY.has(e.path))
      .map((e) => ({ path: e.path, sha: e.sha }));
  } else {
    // Single-file mode — upstream.path points to a file
    const pathParts = upstream.path.split("/");
    const fileName = pathParts.pop();
    if (LOCAL_ONLY.has(fileName)) {
      core.info(`[${name}] upstream.path points to ${fileName}, skipping.`);
      return;
    }
    const parentSha = pathParts.length
      ? await resolveSubtreeSha(octokit, upOwner, upRepo, commit.tree.sha, pathParts.join("/"))
      : commit.tree.sha;
    if (!parentSha) throw new Error(`Could not resolve parent tree for '${upstream.path}'`);

    const { data: parentTree } = await octokit.rest.git.getTree({
      owner: upOwner,
      repo: upRepo,
      tree_sha: parentSha,
    });
    const fileEntry = parentTree.tree.find((e) => e.path === fileName && e.type === "blob");
    if (!fileEntry) throw new Error(`File not found in upstream tree: ${fileName}`);
    upstreamFiles = [{ path: fileName, sha: fileEntry.sha }];
  }

  // 3. Compare upstream SHAs against local files
  const localFiles = walkDir(localDir, localDir).filter((f) => !LOCAL_ONLY.has(f));
  const upstreamPaths = new Set(upstreamFiles.map((f) => f.path));
  const localPaths = new Set(localFiles);

  const toUpdate = []; // { path, upstreamSha }
  const toDelete = []; // paths

  for (const uf of upstreamFiles) {
    const localPath = join(localDir, uf.path);
    try {
      const localContent = readFileSync(localPath);
      const localSha = gitBlobSha(localContent);
      if (localSha !== uf.sha) {
        toUpdate.push(uf);
      }
    } catch {
      // File doesn't exist locally — new file
      toUpdate.push(uf);
    }
  }

  for (const lf of localFiles) {
    if (!upstreamPaths.has(lf)) {
      toDelete.push(lf);
    }
  }

  if (toUpdate.length === 0 && toDelete.length === 0) {
    core.info(`[${name}] Up to date.`);
    return;
  }

  core.info(
    `[${name}] Changes detected: ${toUpdate.length} update(s), ${toDelete.length} deletion(s).`,
  );

  // 4. Check for existing open sync PR
  const { data: openPrs } = await octokit.rest.pulls.list({
    owner: repoOwner,
    repo: repoName,
    state: "open",
    head: `${repoOwner}:${branchName}`,
  });
  const existingPr = openPrs[0] || null;

  // 5. Build the sync commit
  // Get main HEAD
  const { data: mainRef } = await octokit.rest.git.getRef({
    owner: repoOwner,
    repo: repoName,
    ref: "heads/main",
  });
  const mainSha = mainRef.object.sha;
  const { data: mainCommit } = await octokit.rest.git.getCommit({
    owner: repoOwner,
    repo: repoName,
    commit_sha: mainSha,
  });

  // Fetch content for changed files and create blobs in our repo
  const treeEntries = [];

  for (const uf of toUpdate) {
    const { data: blob } = await octokit.rest.git.getBlob({
      owner: upOwner,
      repo: upRepo,
      file_sha: uf.sha,
    });
    const { data: newBlob } = await octokit.rest.git.createBlob({
      owner: repoOwner,
      repo: repoName,
      content: blob.content,
      encoding: "base64",
    });
    treeEntries.push({
      path: posix.join("packages", name, uf.path),
      mode: "100644",
      type: "blob",
      sha: newBlob.sha,
    });
  }

  for (const df of toDelete) {
    treeEntries.push({
      path: posix.join("packages", name, df),
      mode: "100644",
      type: "blob",
      sha: null,
    });
  }

  const { data: newTree } = await octokit.rest.git.createTree({
    owner: repoOwner,
    repo: repoName,
    base_tree: mainCommit.tree.sha,
    tree: treeEntries,
  });

  const { data: newCommit } = await octokit.rest.git.createCommit({
    owner: repoOwner,
    repo: repoName,
    message: `chore: sync ${name} from upstream`,
    tree: newTree.sha,
    parents: [mainSha],
  });

  // 6. Create or force-update the branch
  if (existingPr) {
    await octokit.rest.git.updateRef({
      owner: repoOwner,
      repo: repoName,
      ref: `heads/${branchName}`,
      sha: newCommit.sha,
      force: true,
    });
    core.info(`[${name}] Updated branch ${branchName}.`);
  } else {
    try {
      await octokit.rest.git.createRef({
        owner: repoOwner,
        repo: repoName,
        ref: `refs/heads/${branchName}`,
        sha: newCommit.sha,
      });
    } catch (err) {
      if (err.status === 422) {
        // Branch exists without an open PR (stale) — force-update it
        await octokit.rest.git.updateRef({
          owner: repoOwner,
          repo: repoName,
          ref: `heads/${branchName}`,
          sha: newCommit.sha,
          force: true,
        });
      } else {
        throw err;
      }
    }
    core.info(`[${name}] Created branch ${branchName}.`);
  }

  // 7. Create or update the PR
  const prBody = buildPrBody(upstream, today);
  const prTitle = `chore: sync ${name} from upstream`;

  if (existingPr) {
    await octokit.rest.pulls.update({
      owner: repoOwner,
      repo: repoName,
      pull_number: existingPr.number,
      body: prBody,
    });
    core.info(`[${name}] Updated PR #${existingPr.number}.`);
  } else {
    const { data: pr } = await octokit.rest.pulls.create({
      owner: repoOwner,
      repo: repoName,
      title: prTitle,
      body: prBody,
      head: branchName,
      base: "main",
    });
    core.info(`[${name}] Opened PR #${pr.number}.`);
  }
}
